# greet

A tiny command that prints a greeting.

    node bin/greet.mjs Mike
    Hello, Mike!

Use `--shout` to print the whole greeting in uppercase. Put it before or after the name; omit the name to greet the world.

    node bin/greet.mjs --shout Mike
    HELLO, MIKE!

Run the tests with `npm test`.
#!/usr/bin/env node
// greet: prints a friendly greeting.
// Usage: greet [--shout] [name]
export function greet(name = 'world') {
  return `Hello, ${name}!`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const args = process.argv.slice(2);
  const shout = args.includes('--shout');
  const name = args.find((arg) => arg !== '--shout');
  const message = greet(name);
  console.log(shout ? message.toUpperCase() : message);
}
